// OKUConnect Telegram router: decides what to show for every message or button press.
// Language choice, conversation number and feedback are kept in this workflow's static data
// (saved only for published/production runs).
const sd = $getWorkflowStaticData('global');
sd.users = sd.users || {};
sd.feedback = sd.feedback || [];

const TOPICS = {
  en: [
    { id: 'kad', icon: '🪪', title: 'Register as OKU and get a Kad OKU', q: ['How do I register for a Kad OKU?', 'What documents do I need to register as OKU?', 'What can I use my Kad OKU for?'] },
    { id: 'jkm', icon: '💰', title: 'Money help from JKM', q: ['What financial aid can OKU get from JKM?', 'Who can apply for JKM aid for OKU?', 'How do I apply for JKM financial aid?'] },
    { id: 'pks', icon: '💼', title: 'PERKESO (SOCSO) benefits', q: ['What benefits does PERKESO give for disability?', 'What is the PERKESO Invalidity Pension?', 'How do I make a claim with PERKESO?'] },
    { id: 'kwsp', icon: '🏦', title: 'KWSP (EPF) savings', q: ['Can I withdraw my KWSP savings if I have a disability?', 'What documents does KWSP need for a disability withdrawal?'] },
    { id: 'hak', icon: '⚖️', title: 'Your rights as OKU', q: ['What rights do OKU have under Akta OKU 2008?', 'What are my rights at work as an OKU?', 'What can I do if a public place is not accessible?'] },
    { id: 'edu', icon: '🎓', title: 'Education help', q: ['What education help is there for OKU students?', 'What is the BKOKU financial aid for OKU students?'] },
    { id: 'kerja', icon: '🛠️', title: 'Jobs and training', q: ['What is the EPOKU allowance?', 'What is the Job Coach programme?', 'What is Bengkel Daya?'] },
    { id: 'agensi', icon: '🏛️', title: 'Agencies and organisations', q: ['Which agencies help OKU in Malaysia?', 'Where can I find an OKU care centre?'] },
  ],
  ms: [
    { id: 'kad', icon: '🪪', title: 'Daftar OKU dan Kad OKU', q: ['Bagaimana cara memohon Kad OKU?', 'Apakah dokumen yang diperlukan untuk mendaftar sebagai OKU?', 'Apakah kegunaan Kad OKU?'] },
    { id: 'jkm', icon: '💰', title: 'Bantuan kewangan JKM', q: ['Apakah bantuan kewangan JKM untuk OKU?', 'Siapa yang layak memohon bantuan JKM untuk OKU?', 'Bagaimana cara memohon bantuan kewangan JKM?'] },
    { id: 'pks', icon: '💼', title: 'Faedah PERKESO', q: ['Apakah faedah PERKESO untuk hilang upaya?', 'Apakah Pencen Ilat PERKESO?', 'Bagaimana cara membuat tuntutan dengan PERKESO?'] },
    { id: 'kwsp', icon: '🏦', title: 'Simpanan KWSP', q: ['Bolehkah saya mengeluarkan simpanan KWSP jika saya hilang upaya?', 'Apakah dokumen yang KWSP perlukan untuk pengeluaran hilang upaya?'] },
    { id: 'hak', icon: '⚖️', title: 'Hak anda sebagai OKU', q: ['Apakah hak OKU di bawah Akta OKU 2008?', 'Apakah hak saya sebagai OKU di tempat kerja?', 'Apa yang boleh saya buat jika tempat awam tidak mesra OKU?'] },
    { id: 'edu', icon: '🎓', title: 'Bantuan pendidikan', q: ['Apakah bantuan pendidikan untuk pelajar OKU?', 'Apakah bantuan kewangan BKOKU untuk pelajar OKU?'] },
    { id: 'kerja', icon: '🛠️', title: 'Pekerjaan dan latihan', q: ['Apakah Elaun Pekerja OKU (EPOKU)?', 'Apakah program Job Coach?', 'Apakah Bengkel Daya?'] },
    { id: 'agensi', icon: '🏛️', title: 'Agensi dan pertubuhan', q: ['Agensi manakah yang membantu OKU di Malaysia?', 'Di manakah saya boleh mencari pusat jagaan OKU?'] },
  ],
};

const SITES = [
  { name: 'JKM', url: 'https://www.jkm.gov.my', en: 'OKU registration, Kad OKU and financial aid', ms: 'Pendaftaran OKU, Kad OKU dan bantuan kewangan' },
  { name: 'MyGOV – OKU', url: 'https://www.malaysia.gov.my/my/personas/oku', en: 'Government portal guide for OKU', ms: 'Panduan portal kerajaan untuk OKU' },
  { name: 'PERKESO', url: 'https://www.perkeso.gov.my', en: 'Benefits for workers who become disabled', ms: 'Faedah untuk pekerja yang hilang upaya' },
  { name: 'KWSP', url: 'https://www.kwsp.gov.my', en: 'Withdrawing savings because of disability', ms: 'Pengeluaran simpanan kerana hilang upaya' },
  { name: 'KKM', url: 'https://www.moh.gov.my', en: 'Health services and medical reports', ms: 'Perkhidmatan kesihatan dan laporan perubatan' },
];

const NGOS = [
  { name: 'NASOM', url: 'https://www.nasom.org.my', en: 'National Autism Society of Malaysia: autism support and centres', ms: 'Persatuan Autisme Kebangsaan Malaysia: sokongan dan pusat autisme' },
  { name: 'MAB', url: 'https://mab.org.my', en: 'Malaysian Association for the Blind: support for people with vision loss', ms: 'Persatuan Orang Buta Malaysia: sokongan untuk orang cacat penglihatan' },
  { name: 'Kiwanis Down Syndrome Foundation', url: 'https://kiwanis.org.my/projects/kiwanis-down-syndrome-foundation', en: 'Early intervention for children with Down syndrome', ms: 'Intervensi awal untuk kanak-kanak sindrom Down' },
  { name: 'Malaysian CARE – PWD Directory', url: 'https://malaysiancare.org/pwd', en: 'Directory to find more services and NGOs near you', ms: 'Direktori untuk mencari lebih banyak perkhidmatan dan NGO berhampiran anda' },
];

const TXT = {
  en: {
    home: '🏠 <b>Main menu</b>\n\nChoose what you need below, or simply type your question at any time.\n\nℹ️ Answers come from official sources. Always check important decisions with the agency.',
    btnTopics: '📚 Topics & questions', btnAsk: '💬 Ask a question', btnSites: '🌐 Official websites', btnNgo: '🤝 NGOs', btnHelp: '📖 How to use', btnLang: '🔤 Bahasa / Language', btnBack: '⬅️ Back', btnHome: '🏠 Main menu', btnMore: '📚 More questions', btnNew: '🔄 New conversation', btnUp: '👍 Helpful', btnDown: '👎 Not helpful', btnSub: '🔔 Weekly updates', btnSubOn: '🔔 Turn on weekly updates', btnSubOff: '🔕 Turn off weekly updates',
    sub: (on) => `🔔 <b>Weekly updates</b>\n\nGet a short message every Monday when OKU aid and service information is updated, plus a helpful tip.\n\nStatus: <b>${on ? 'On ✅' : 'Off'}</b>`,
    subDone: 'Weekly updates turned on ✅', unsubDone: 'Weekly updates turned off',
    topics: '📚 <b>Topics</b>\n\nChoose a topic to see questions you can ask.',
    topic: (t) => `${t.icon} <b>${t.title}</b>\n\nTap a question. The answer will be sent to you.`,
    ask: '💬 <b>Ask a question</b>\n\nType your question in a normal message below, in English or Bahasa Malaysia.\n\nExample: <i>How do I register for a Kad OKU?</i>\n\n⚠️ Do not send your IC number or other private details.',
    sites: '🌐 <b>Official websites</b>\n\nGo to the agency website to apply or check details.\n\n',
    ngo: '🤝 <b>NGOs that support OKU and caregivers</b>\n\n',
    help: '📖 <b>How to use OKUConnect</b>\n\n1. Tap <b>Topics &amp; questions</b> and choose a question, or type your own question.\n2. Wait a few seconds for the answer.\n3. Each answer shows its official source. Check important details with the agency.\n4. Tap 👍 or 👎 to tell us if the answer helped.\n\n<b>Commands</b>\n/menu – Main menu\n/topics – Topics and questions\n/language – Change language\n/new – Start a new conversation\n/subscribe – Weekly updates on\n/unsubscribe – Weekly updates off\n/help – How to use\n\n⚠️ Do not send your IC number or other private details.\n\nOKUConnect is a final year project prototype. It does not replace advice from government agencies.',
    textOnly: 'Sorry, I can only read text messages. Please type your question.',
    newDone: '🔄 New conversation started. Earlier questions are forgotten.',
    thanks: 'Thank you for your feedback!',
  },
  ms: {
    home: '🏠 <b>Menu utama</b>\n\nPilih apa yang anda perlukan di bawah, atau taip soalan anda pada bila-bila masa.\n\nℹ️ Jawapan diambil daripada sumber rasmi. Sentiasa sahkan keputusan penting dengan agensi.',
    btnTopics: '📚 Topik & soalan', btnAsk: '💬 Tanya soalan', btnSites: '🌐 Laman web rasmi', btnNgo: '🤝 NGO', btnHelp: '📖 Cara guna', btnLang: '🔤 Bahasa / Language', btnBack: '⬅️ Kembali', btnHome: '🏠 Menu utama', btnMore: '📚 Soalan lain', btnNew: '🔄 Perbualan baharu', btnUp: '👍 Membantu', btnDown: '👎 Tidak membantu', btnSub: '🔔 Kemas kini mingguan', btnSubOn: '🔔 Hidupkan kemas kini mingguan', btnSubOff: '🔕 Matikan kemas kini mingguan',
    sub: (on) => `🔔 <b>Kemas kini mingguan</b>\n\nTerima mesej ringkas setiap Isnin apabila maklumat bantuan dan perkhidmatan OKU dikemas kini, berserta tip berguna.\n\nStatus: <b>${on ? 'Hidup ✅' : 'Mati'}</b>`,
    subDone: 'Kemas kini mingguan dihidupkan ✅', unsubDone: 'Kemas kini mingguan dimatikan',
    topics: '📚 <b>Topik</b>\n\nPilih topik untuk melihat soalan yang boleh ditanya.',
    topic: (t) => `${t.icon} <b>${t.title}</b>\n\nTekan soalan. Jawapan akan dihantar kepada anda.`,
    ask: '💬 <b>Tanya soalan</b>\n\nTaip soalan anda dalam mesej biasa di bawah, dalam Bahasa Malaysia atau English.\n\nContoh: <i>Bagaimana cara memohon Kad OKU?</i>\n\n⚠️ Jangan hantar nombor kad pengenalan atau maklumat peribadi lain.',
    sites: '🌐 <b>Laman web rasmi</b>\n\nPergi ke laman web agensi untuk memohon atau menyemak butiran.\n\n',
    ngo: '🤝 <b>NGO yang membantu OKU dan penjaga</b>\n\n',
    help: '📖 <b>Cara guna OKUConnect</b>\n\n1. Tekan <b>Topik &amp; soalan</b> dan pilih soalan, atau taip soalan anda sendiri.\n2. Tunggu beberapa saat untuk jawapan.\n3. Setiap jawapan menunjukkan sumber rasmi. Sahkan butiran penting dengan agensi.\n4. Tekan 👍 atau 👎 untuk memberitahu kami sama ada jawapan membantu.\n\n<b>Arahan</b>\n/menu – Menu utama\n/topics – Topik dan soalan\n/language – Tukar bahasa\n/new – Mula perbualan baharu\n/subscribe – Hidupkan kemas kini mingguan\n/unsubscribe – Matikan kemas kini mingguan\n/help – Cara guna\n\n⚠️ Jangan hantar nombor kad pengenalan atau maklumat peribadi lain.\n\nOKUConnect ialah prototaip projek tahun akhir. Ia tidak menggantikan nasihat agensi kerajaan.',
    textOnly: 'Maaf, saya hanya boleh membaca mesej teks. Sila taip soalan anda.',
    newDone: '🔄 Perbualan baharu dimulakan. Soalan sebelum ini telah dilupakan.',
    thanks: 'Terima kasih atas maklum balas anda!',
  },
};

const LANG_PICK = {
  text: '👋 <b>Selamat datang ke OKUConnect!</b>\n<b>Welcome to OKUConnect!</b>\n\nMaklumat bantuan, hak dan perkhidmatan untuk OKU di Malaysia.\nInformation on aid, rights and services for OKU in Malaysia.\n\nSila pilih bahasa / Please choose your language:',
  keyboard: [[{ text: '🇲🇾 Bahasa Malaysia', callback_data: 'lang:ms' }, { text: '🇬🇧 English', callback_data: 'lang:en' }]],
};

function detectLang(text) {
  const ms = ['yang','dan','untuk','saya','anda','bagaimana','apakah','boleh','tidak','dengan','bantuan','memohon','cara','siapa','bila','manakah','perlu','di','ke','ini'];
  const words = (text.toLowerCase().match(/[a-z]+/g) || []);
  const hits = words.filter((w) => ms.includes(w)).length;
  return hits >= 1 ? 'ms' : 'en';
}

function screen(name, L, arg) {
  const t = TXT[L];
  const back = (to) => [{ text: t.btnBack, callback_data: to }];
  switch (name) {
    case 'lang': return LANG_PICK;
    case 'home': return { text: t.home, keyboard: [
      [{ text: t.btnTopics, callback_data: 'topics' }, { text: t.btnAsk, callback_data: 'ask' }],
      [{ text: t.btnSites, callback_data: 'sites' }, { text: t.btnNgo, callback_data: 'ngo' }],
      [{ text: t.btnSub, callback_data: 'sub' }, { text: t.btnHelp, callback_data: 'help' }],
      [{ text: t.btnLang, callback_data: 'langpick' }],
    ] };
    case 'topics': {
      const rows = TOPICS[L].map((tp) => [{ text: `${tp.icon} ${tp.title}`, callback_data: `t:${tp.id}` }]);
      rows.push(back('home'));
      return { text: t.topics, keyboard: rows };
    }
    case 'topic': {
      const tp = TOPICS[L].find((x) => x.id === arg) || TOPICS[L][0];
      const rows = tp.q.map((q, i) => [{ text: q, callback_data: `q:${tp.id}:${i}` }]);
      rows.push(back('topics'));
      return { text: t.topic(tp), keyboard: rows };
    }
    case 'ask': return { text: t.ask, keyboard: [back('home')] };
    case 'sites': return {
      text: t.sites + SITES.map((s) => `• <b>${s.name}</b>: ${s[L]}`).join('\n'),
      keyboard: [...SITES.map((s) => [{ text: `🔗 ${s.name}`, url: s.url }]), back('home')],
    };
    case 'ngo': return {
      text: t.ngo + NGOS.map((s) => `• <b>${s.name}</b>: ${s[L]}`).join('\n'),
      keyboard: [...NGOS.map((s) => [{ text: `🔗 ${s.name}`, url: s.url }]), back('home')],
    };
    case 'help': return { text: t.help, keyboard: [back('home')] };
    case 'sub': {
      const on = !!(arg);
      return { text: t.sub(on), keyboard: [[on ? { text: t.btnSubOff, callback_data: 'unsub' } : { text: t.btnSubOn, callback_data: 'subon' }], back('home')] };
    }
  }
  return screen('home', L);
}

// ---------- Read the Telegram update ----------
const upd = $json;
let chatId, text = null, data = null, messageId = null, callbackId = null;
if (upd.callback_query) {
  const cq = upd.callback_query;
  callbackId = cq.id;
  data = cq.data || '';
  chatId = cq.message ? cq.message.chat.id : cq.from.id;
  messageId = cq.message ? cq.message.message_id : null;
} else if (upd.message) {
  chatId = upd.message.chat.id;
  text = (upd.message.text || '').trim();
} else {
  return { json: { mode: 'none' } };
}

const key = String(chatId);
const user = sd.users[key] = sd.users[key] || { session: 0 };
const out = { mode: 'menu', chat_id: chatId, callback_id: callbackId, callback_text: null };

function show(name, arg, { edit = true } = {}) {
  const L = user.lang || 'ms';
  const s = screen(name, L, arg);
  const payload = { chat_id: chatId, text: s.text, parse_mode: 'HTML', disable_web_page_preview: true, reply_markup: { inline_keyboard: s.keyboard } };
  if (edit && messageId) { payload.message_id = messageId; out.method = 'editMessageText'; }
  else out.method = 'sendMessage';
  out.payload = payload;
}
function ask(question, topicId, fromButton) {
  if (!user.lang) user.lang = detectLang(question);
  out.mode = 'ask';
  out.ask = {
    question,
    lang: user.lang,
    topic: topicId || null,
    from_button: !!fromButton,
    session_id: `tg-${chatId}-${user.session || 0}`,
  };
}
function setSub(on) {
  user.subscribed = on;
  out.subscription = { chat_id: key, lang: user.lang || 'ms', subscribed: on };
}
function notice(msg, then) {
  // Short confirmation followed by a screen, sent as a new message
  show(then, null, { edit: false });
  out.payload.text = msg + '\n\n' + out.payload.text;
}

if (data !== null) {
  // Buttons under answers start with "n:" so menus open as a new message instead of replacing the answer
  let edit = true;
  if (data.startsWith('n:')) { edit = false; data = data.slice(2); }
  if (data.startsWith('lang:')) { user.lang = data.slice(5) === 'en' ? 'en' : 'ms'; if (user.subscribed) setSub(true); show('home', null, { edit }); }
  else if (data === 'langpick') show('lang', null, { edit });
  else if (['home', 'topics', 'ask', 'sites', 'ngo', 'help'].includes(data)) show(data, null, { edit });
  else if (data.startsWith('t:')) show('topic', data.slice(2), { edit });
  else if (data === 'sub') show('sub', user.subscribed, { edit });
  else if (data === 'subon' || data === 'unsub') {
    setSub(data === 'subon');
    show('sub', user.subscribed, { edit });
    out.callback_text = TXT[user.lang || 'ms'][data === 'subon' ? 'subDone' : 'unsubDone'];
  }
  else if (data.startsWith('q:')) {
    const [, tid, idx] = data.split(':');
    const L = user.lang || 'ms';
    const tp = TOPICS[L].find((x) => x.id === tid);
    const q = tp && tp.q[Number(idx)];
    if (q) ask(q, tid, true); else show('topics', null, { edit });
  }
  else if (data === 'new') { user.session = (user.session || 0) + 1; notice(TXT[user.lang || 'ms'].newDone, 'home'); }
  else if (data === 'fb:up' || data === 'fb:dn') {
    sd.feedback.push({ chat: key, vote: data === 'fb:up' ? 'up' : 'down', at: new Date().toISOString() });
    if (sd.feedback.length > 500) sd.feedback = sd.feedback.slice(-500);
    out.mode = 'none';
    out.feedback = { vote: data === 'fb:up' ? 'up' : 'down', question: user.lastQ || '', session_id: `tg-${chatId}-${user.session || 0}` };
    out.callback_text = TXT[user.lang || 'ms'].thanks;
  }
  else show('home', null, { edit });
} else {
  const cmd = text.split(/\s+/)[0].toLowerCase().replace(/@.*$/, '');
  if (!text) { show('home', null, { edit: false }); out.payload.text = TXT[user.lang || 'ms'].textOnly; out.payload.reply_markup = { inline_keyboard: [[{ text: TXT[user.lang || 'ms'].btnHome, callback_data: 'n:home' }]] }; }
  else if (cmd === '/start') { if (user.lang) show('home', null, { edit: false }); else show('lang', null, { edit: false }); }
  else if (cmd === '/menu') show('home', null, { edit: false });
  else if (cmd === '/topics') show('topics', null, { edit: false });
  else if (cmd === '/language' || cmd === '/bahasa') show('lang', null, { edit: false });
  else if (cmd === '/help') show('help', null, { edit: false });
  else if (cmd === '/subscribe' || cmd === '/unsubscribe') { setSub(cmd === '/subscribe'); show('sub', user.subscribed, { edit: false }); }
  else if (cmd === '/new') { user.session = (user.session || 0) + 1; notice(TXT[user.lang || 'ms'].newDone, 'home'); }
  else if (cmd.startsWith('/')) show('home', null, { edit: false });
  else ask(text, null, false);
}

return { json: out };

// Turns the RAG answer into Telegram-safe HTML, splits long answers, and adds follow-up buttons.
const r = $('Router').first().json;
const res = $input.first().json || {};
const L = r.ask.lang;
// Remember the last question so 👍/👎 feedback can be linked to it
const sd = $getWorkflowStaticData('global');
sd.users = sd.users || {};
const me = sd.users[String(r.chat_id)] = sd.users[String(r.chat_id)] || { session: 0 };
me.lastQ = r.ask.question;
const T = {
  en: { fail: 'Sorry, the answer could not be loaded. Please try again in a moment.', up: '👍 Helpful', down: '👎 Not helpful', more: '📚 More questions', home: '🏠 Main menu', nw: '🔄 New conversation' },
  ms: { fail: 'Maaf, jawapan tidak dapat dimuatkan. Sila cuba lagi sebentar lagi.', up: '👍 Membantu', down: '👎 Tidak membantu', more: '📚 Soalan lain', home: '🏠 Menu utama', nw: '🔄 Perbualan baharu' },
}[L === 'en' ? 'en' : 'ms'];

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let answer = typeof res.output === 'string' && res.output.trim() ? res.output.trim() : T.fail;

let html = esc(answer)
  .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2">$1</a>')
  .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
  .replace(/^#{1,6}\s*(.+)$/gm, '<b>$1</b>')
  .replace(/^\s*[-*]\s+/gm, '• ');

if (r.ask.from_button) html = `❓ <i>${esc(r.ask.question)}</i>\n\n` + html;

// Telegram allows 4096 characters per message
const parts = [];
let current = '';
for (const para of html.split('\n\n')) {
  if ((current + '\n\n' + para).length > 3900 && current) { parts.push(current); current = para; }
  else current = current ? current + '\n\n' + para : para;
}
if (current) parts.push(current);

const rows = [[{ text: T.up, callback_data: 'fb:up' }, { text: T.down, callback_data: 'fb:dn' }]];
const nav = [];
if (r.ask.topic) nav.push({ text: T.more, callback_data: `n:t:${r.ask.topic}` });
nav.push({ text: T.home, callback_data: 'n:home' });
rows.push(nav);
rows.push([{ text: T.nw, callback_data: 'n:new' }]);

return parts.map((p, i) => ({
  json: {
    payload: {
      chat_id: r.chat_id,
      text: p,
      parse_mode: 'HTML',
      disable_web_page_preview: true,
      ...(i === parts.length - 1 ? { reply_markup: { inline_keyboard: rows } } : {}),
    },
  },
}));
